import { rivalHeadline } from './story';
import { initialRivals, priceIndexOf, stepRivals } from '../rivals';
import type { System } from './types';

/** Rival operators expand and reprice; the resulting price index scales every
 *  offer generated by contractMarket later this month. */
export const rivalsSystem: System = {
  id: 'rivals',
  run: ({ s, rng, log }) => {
    if (!s.rivals) s.rivals = initialRivals(s.seed);
    const before = s.rivals.map((r) => ({ r, accels: r.accels, priceMult: r.priceMult }));
    stepRivals(s, rng); // one rng draw per rival, fixed order
    s.marketPriceIndex = priceIndexOf(s);
    if (s.month % 6 === 0) {
      let top = before[0];
      let added = 0;
      for (const b of before) {
        const d = b.r.accels - b.accels;
        if (d > added) { added = d; top = b; }
      }
      const cut = (top.priceMult - top.r.priceMult) * 100;
      const move = cut >= 0.05 ? `cut prices ${cut.toFixed(0)}%` : cut <= -0.05 ? `raised prices ${(-cut).toFixed(0)}%` : 'held prices flat';
      const hl = rivalHeadline(s, top.r.id, top.r.name); if (hl) log('info', `📰 ${hl}`);
      log('info', `${top.r.name} added ${Math.round(added).toLocaleString('en-US')} accelerators and ${move} — competition sets the market: your share of supply moves the price index.`);
    }
  },
};
